// ===== CONFIG (sin secretos). Reemplaza los valores REEMPLAZAR_* después de importar. =====
// Las API keys y el token del bot NO van aquí: viven en Credenciales de n8n.
const CONFIG = {
  modo: 'SIMULADO',
  empresa: 'Valoria Casa de Bolsa (ficticia)',
  pages_base_url: 'https://juliozarate.github.io/ai-tools-proyecto-final-Zarate',
  anthropic_url: 'https://api.anthropic.com/v1/messages',
  modelo: 'claude-haiku-5-5',
  tarifas: {
    proveedor: 'Anthropic',
    entrada_usd_mtok: 0.10,
    salida_usd_mtok: 0.50,
    cache_lectura_usd_mtok: 0.01,
    umbral_prompt_tokens: 100000,
    entrada_alta_usd_mtok: 0.50,
    salida_alta_usd_mtok: 2.50,
    fecha_consulta: '2026-11-03'
  },
  presupuesto_caso_usd_default: 0.01,
  presupuesto_caso_usd_max: 0.02,
  reserva_pct: 0.20,
  max_llamadas_caso: 10,
  max_iteraciones_calidad: 3,
  max_correcciones_a2: 1,
  tiempo_max_caso_ms: 120000,
  max_tokens: { A1: 500, A2: 700, A3: 900, A4: 500 },
  aprobacion_minutos: 30,
  usuarios: {
    'REEMPLAZAR_ID_TELEGRAM_ASESOR': 'asesor',
    'REEMPLAZAR_ID_TELEGRAM_ANALISTA': 'analista'
  },
  asesor_chat_id: 'REEMPLAZAR_CHAT_ID_ASESOR',
  sal_seudonimo: 'valoria-2026',
  max_len_texto: 600,
  patrones_bloqueo: [
    'ignor(a|e|ar|en)\\s+(las|tus|todas|sus|previous|all|the)',
    'instrucciones\\s+(anteriores|previas|del sistema|originales)',
    'system\\s*prompt', 'prompt del sistema', 'tu prompt',
    'revela(r)?\\s', 'api[ _-]?key', '\\btoken\\b', 'contrase(ñ|n)a', 'password', 'credencial',
    'desactiva(r)?\\s', 'modo\\s+(desarrollador|dios|admin|developer)', 'jailbreak',
    '<\\s*script', 'https?://', 'www\\.'
  ]
};

// ===== Utilidades compartidas (se copian en cada nodo Code que las usa) =====
function hashCorto(s) {
  let h = 2166136261;
  s = String(s);
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return ('00000000' + (h >>> 0).toString(16)).slice(-8);
}
function ahoraISO() { return new Date().toISOString(); }
function enmascarar(t) {
  return String(t || '')
    .replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[correo]')
    .replace(/\b[A-Z]{4}\d{6}[HM][A-Z]{5}[A-Z0-9]\d\b/gi, '[curp]')
    .replace(/\b[A-ZÑ&]{3,4}\d{6}[A-Z0-9]{3}\b/gi, '[rfc]')
    .replace(/\b(?:\d[ -]?){13,19}\b/g, '[numero]')
    .replace(/\+?\d[\d\s-]{8,}\d/g, '[telefono]')
    .slice(0, 600);
}
function extraerJSON(texto) {
  if (texto === null || texto === undefined) return null;
  if (typeof texto === 'object') return texto;
  try { return JSON.parse(texto); } catch (e) { /* sigue */ }
  const i = texto.indexOf('{'), j = texto.lastIndexOf('}');
  if (i >= 0 && j > i) { try { return JSON.parse(texto.slice(i, j + 1)); } catch (e) { /* sigue */ } }
  return null;
}
function estimarTokens(texto) { return Math.ceil(String(texto || '').length / 3); }
function tarifaPara(tokensPrompt, t) {
  const alta = tokensPrompt > t.umbral_prompt_tokens;
  return { pin: alta ? t.entrada_alta_usd_mtok : t.entrada_usd_mtok, pout: alta ? t.salida_alta_usd_mtok : t.salida_usd_mtok, pcache: alta ? t.cache_lectura_usd_mtok * 5 : t.cache_lectura_usd_mtok };
}
// Ci = (Tentrada*Pentrada + Tsalida*Psalida + Tcache*Pcache) / 1,000,000
function costoUSD(tin, tout, tcache, t) {
  const tf = tarifaPara(tin + tcache, t);
  return (tin * tf.pin + tout * tf.pout + tcache * tf.pcache) / 1000000;
}
function redondear6(x) { return Math.round(x * 1e6) / 1e6; }

// Guardia del loop de seguridad y costo: se evalúa ANTES de cada llamada LLM.
function guardia(st, agente, system, user) {
  const cfg = CONFIG;
  const permitidos = { A1: true, A2: true, A3: true, A4: true };
  const maxTok = cfg.max_tokens[agente];
  const estTin = estimarTokens(system) + estimarTokens(user);
  const estimado = costoUSD(estTin, maxTok, 0, cfg.tarifas);
  const disponible = st.limite_costo_usd * (1 - cfg.reserva_pct) - st.gasto_usd;
  const transcurrido = Date.now() - st.inicio_ms;
  let motivo = null;
  if (!permitidos[agente]) motivo = 'agente_no_autorizado';
  else if (st.llamadas.length >= cfg.max_llamadas_caso) motivo = 'limite_llamadas';
  else if (transcurrido > cfg.tiempo_max_caso_ms) motivo = 'limite_tiempo';
  else if (estimado > disponible) motivo = 'presupuesto';
  return { ok: motivo === null, motivo: motivo, estimado_usd: redondear6(estimado), disponible_usd: redondear6(disponible), max_tokens: maxTok };
}

function cuerpoLLM(system, user, maxTokens) {
  // Haiku 5.5: sin temperature/top_k ni prefill (la API los rechaza).
  return { model: CONFIG.modelo, max_tokens: maxTokens, system: system, messages: [{ role: 'user', content: user }] };
}

// Registra la llamada (éxito o error) y devuelve el texto de la respuesta.
function registrarLlamada(st, agente, etapa, resp, prep) {
  const cfg = CONFIG;
  const id = st.caso_id + '-L' + String((st.llamadas_previas || 0) + st.llamadas.length + 1).padStart(2, '0');
  const fila = {
    fecha_hora: ahoraISO(), caso_id: st.caso_id, llamada_id: id, etapa: etapa, agente: agente,
    proveedor: cfg.tarifas.proveedor, modelo: cfg.modelo, tokens_entrada: 0, tokens_salida: 0, tokens_cache: 0,
    duracion_voz_seg: 0, unidad_cobro: 'tokens', tarifa_entrada: cfg.tarifas.entrada_usd_mtok, tarifa_salida: cfg.tarifas.salida_usd_mtok,
    costo_usd: 0, moneda: 'USD', estado: 'ok', reintento: 0, origen_dato: 'medido_api', iteracion: st.iteracion || 0,
    duracion_ms: Date.now() - (prep.t0 || Date.now())
  };
  let texto = null, error = null;
  if (!resp || resp.error || !resp.content) {
    error = resp && resp.error ? (resp.error.message || JSON.stringify(resp.error)).slice(0, 200) : 'respuesta_vacia';
    fila.estado = 'error';
    // Si la API falló no hay uso reportado: se registra la estimación de entrada, marcada como estimada.
    fila.tokens_entrada = prep.est_tokens_entrada || 0;
    fila.costo_usd = 0;
    fila.origen_dato = 'estimado_sin_cobro_confirmado';
  } else {
    const u = resp.usage || {};
    fila.tokens_entrada = u.input_tokens || 0;
    fila.tokens_salida = u.output_tokens || 0;
    fila.tokens_cache = (u.cache_read_input_tokens || 0);
    fila.costo_usd = redondear6(costoUSD(fila.tokens_entrada, fila.tokens_salida, fila.tokens_cache, cfg.tarifas));
    const bloque = (resp.content || []).filter(function (b) { return b.type === 'text'; })[0];
    texto = bloque ? bloque.text : null;
    if (!texto) { error = 'sin_texto (stop_reason=' + resp.stop_reason + ')'; fila.estado = 'sin_texto'; }
    if (resp.stop_reason === 'refusal') { error = 'refusal'; fila.estado = 'refusal'; }
  }
  st.gasto_usd = redondear6(st.gasto_usd + fila.costo_usd);
  st.llamadas.push(fila);
  return { texto: texto, error: error, llamada_id: id };
}

function anotar(st, paso, agente, estado, entrada, salida, extra) {
  const e = extra || {};
  st.traza.push({
    caso_id: st.caso_id, paso: st.traza.length + 1, agente: agente, accion: paso, estado: estado,
    entrada_resumen: String(entrada || '').slice(0, 300), salida_resumen: String(salida || '').slice(0, 500),
    skill: e.skill || '', version_skill: e.version_skill || '', huella_skill: e.huella_skill || '',
    llamada_id: e.llamada_id || '', version_propuesta: st.version_propuesta || 0, iteracion: st.iteracion || 0,
    timestamp: ahoraISO()
  });
}

// Nodo: "Normalizar y validar entrada" — entrada única para Telegram y voz.
// Guardrails aplicados aquí, ANTES de cualquier llamada a un modelo:
// acceso (lista de usuarios), longitud, patrones de inyección/URLs, formato de folio, modo SIMULADO.
const ev = $input.first().json;
const cfg = CONFIG;
const ctx = { recibido_en: ahoraISO(), modo: cfg.modo, motivo: '', demo: '', presupuesto_solicitado: null };

function nuevoCasoId() {
  const d = new Date();
  const p = function (n) { return String(n).padStart(2, '0'); };
  const abc = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let s = '';
  for (let i = 0; i < 4; i++) s += abc[Math.floor(Math.random() * abc.length)];
  return 'VAL-' + String(d.getUTCFullYear()).slice(2) + p(d.getUTCMonth() + 1) + p(d.getUTCDate()) + '-' + s;
}
function bloqueado(texto) {
  return cfg.patrones_bloqueo.filter(function (p) { return new RegExp(p, 'i').test(texto); });
}
function extraerParametros(texto) {
  // Parámetros de prueba permitidos: demo=falla_v1 y presupuesto=<usd> (solo puede BAJAR el límite).
  let t = texto;
  const mDemo = t.match(/\bdemo=(falla_v1)\b/i);
  if (mDemo) { ctx.demo = mDemo[1].toLowerCase(); t = t.replace(mDemo[0], ''); }
  const mPres = t.match(/\bpresupuesto=([0-9]*\.?[0-9]+)\b/i);
  if (mPres) { ctx.presupuesto_solicitado = Number(mPres[1]); t = t.replace(mPres[0], ''); }
  return t.replace(/\s+/g, ' ').trim();
}

if (ev.update_id !== undefined) {
  ctx.canal = 'telegram';
  ctx.evento_id = 'tg:' + ev.update_id;
  if (ev.callback_query) {
    const cq = ev.callback_query;
    ctx.tipo = 'callback';
    ctx.usuario_raw = String(cq.from.id);
    ctx.chat_id = String(cq.message ? cq.message.chat.id : cq.from.id);
    ctx.callback_id = cq.id;
    const partes = String(cq.data || '').split('|');
    ctx.decision = { accion: partes[0], caso_id: String(partes[1] || '').toUpperCase(), version: Number(partes[2] || 0) };
    ctx.folio = ctx.decision.caso_id;
    ctx.ruta = (partes.length === 3 && (partes[0] === 'ap' || partes[0] === 're')) ? 'decision' : 'invalido';
    if (ctx.ruta === 'invalido') ctx.motivo = 'Botón no reconocido.';
  } else if (ev.message) {
    const m = ev.message;
    ctx.tipo = 'mensaje';
    ctx.usuario_raw = String(m.from.id);
    ctx.chat_id = String(m.chat.id);
    const texto = String(m.text || '').trim();
    const primera = texto.split(/\s+/)[0] || '';
    const cmd = primera.toLowerCase().replace(/@.*/, '');
    const resto = texto.slice(primera.length).trim();
    ctx.comando = cmd;
    if (cmd === '/nuevo') { ctx.ruta = 'nuevo'; ctx.texto = extraerParametros(resto); }
    else if (cmd === '/aclarar') {
      const f = resto.split(/\s+/)[0] || '';
      ctx.ruta = 'aclarar'; ctx.folio = f.toUpperCase(); ctx.texto = extraerParametros(resto.slice(f.length));
    }
    else if (cmd === '/estado') { ctx.ruta = 'estado'; ctx.folio = (resto.split(/\s+/)[0] || '').toUpperCase(); }
    else if (cmd === '/start' || cmd === '/ayuda' || cmd === '/help') { ctx.ruta = 'ayuda'; }
    else { ctx.ruta = 'invalido'; ctx.motivo = 'Comando no reconocido.'; }
  } else {
    ctx.ruta = 'ignorar';
  }
  ctx.rol = cfg.usuarios[ctx.usuario_raw] || '';
  ctx.usuario_ps = 'u_' + hashCorto(cfg.sal_seudonimo + (ctx.usuario_raw || ''));
  if (!ctx.rol && ctx.ruta !== 'ignorar') { ctx.ruta = 'rechazo_acceso'; ctx.motivo = 'Usuario no autorizado.'; }
} else {
  // Herramienta de servidor de ElevenLabs (el nodo Webhook ya validó el encabezado secreto).
  const b = ev.body || {};
  ctx.canal = 'voz';
  ctx.tipo = 'herramienta_voz';
  ctx.rol = 'voz_publica';
  ctx.usuario_ps = 'voz_publica';
  ctx.chat_id = '';
  const accion = String(b.accion || '').toLowerCase().trim();
  const conv = String(b.conversation_id || 'sin_conversacion').slice(0, 80);
  ctx.evento_id = 'voz:' + hashCorto(conv + '|' + JSON.stringify(b));
  if (accion === 'consultar') {
    ctx.ruta = 'estado';
    ctx.folio = String(b.folio || '').toUpperCase().replace(/\s+/g, '').trim();
  } else if (accion === 'crear') {
    ctx.ruta = 'nuevo';
    const restr = Array.isArray(b.restricciones) ? b.restricciones.join(', ') : String(b.restricciones || 'ninguna');
    ctx.texto = extraerParametros(
      'perfil ' + String(b.perfil_riesgo || 'no indicado') +
      ', monto ' + String(b.monto_mxn || 'no indicado') + ' MXN' +
      ', horizonte ' + String(b.horizonte_anios || 'no indicado') + ' años' +
      ', objetivo: ' + String(b.objetivo || 'no indicado').slice(0, 200) +
      ', restricciones: ' + restr.slice(0, 120)
    );
  } else {
    ctx.ruta = 'invalido';
    ctx.motivo = 'La acción debe ser "crear" o "consultar".';
  }
}

// ---- Validaciones de entrada (no se envía nada inválido al modelo) ----
if (cfg.modo !== 'SIMULADO') { ctx.ruta = 'bloqueado'; ctx.motivo = 'El sistema solo opera en modo SIMULADO.'; }
if (ctx.ruta === 'nuevo' || ctx.ruta === 'aclarar') {
  const hallados = bloqueado(ctx.texto || '');
  if (!ctx.texto) { ctx.ruta = 'invalido'; ctx.motivo = 'La solicitud está vacía. Ejemplo: /nuevo perfil moderado, 250 mil pesos a 5 años, solo ESG'; }
  else if (ctx.texto.length > cfg.max_len_texto) { ctx.ruta = 'invalido'; ctx.motivo = 'La solicitud excede ' + cfg.max_len_texto + ' caracteres.'; }
  else if (hallados.length) { ctx.ruta = 'bloqueado'; ctx.motivo = 'La solicitud contiene instrucciones o contenido no permitido (inyección, secretos o URLs) y no se procesó.'; ctx.patrones = hallados.length; }
}
if ((ctx.ruta === 'estado' || ctx.ruta === 'aclarar' || ctx.ruta === 'decision') && !/^VAL-\d{6}-[A-Z0-9]{4}$/.test(ctx.folio || '')) {
  ctx.ruta = 'invalido'; ctx.motivo = 'Folio inválido. Formato: VAL-AAMMDD-XXXX';
}
if (ctx.ruta === 'decision' && ctx.rol !== 'asesor') { ctx.ruta = 'rechazo_permiso'; ctx.motivo = 'Solo el asesor autorizado puede aprobar o rechazar.'; }
if (ctx.ruta === 'aclarar' && ctx.canal !== 'telegram') { ctx.ruta = 'invalido'; ctx.motivo = 'Las aclaraciones se hacen por Telegram.'; }

if (ctx.presupuesto_solicitado !== null) {
  const p = ctx.presupuesto_solicitado;
  ctx.limite_costo_usd = (p > 0 && p < cfg.presupuesto_caso_usd_max) ? p : cfg.presupuesto_caso_usd_default;
} else {
  ctx.limite_costo_usd = cfg.presupuesto_caso_usd_default;
}
ctx.texto_mascarado = enmascarar(ctx.texto || '');
ctx.caso_id = ctx.ruta === 'nuevo' ? nuevoCasoId() : (ctx.folio || '');
delete ctx.texto; // a partir de aquí solo circula la versión enmascarada
return [{ json: ctx }];

// Nodo: "Decidir ruta" — deduplicación persistente por evento_id.
const ctx = Object.assign({}, $('Normalizar y validar entrada').first().json);
const filas = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.evento_id === ctx.evento_id; });
if (ctx.ruta === 'ignorar') return [];
if (filas.length > 0) {
  ctx.duplicado = true;
  ctx.ruta_original = ctx.ruta;
  ctx.caso_previo = filas[0].caso_id || '';
  ctx.ruta = 'duplicado';
} else {
  ctx.duplicado = false;
}
return [{ json: ctx }];

// Nodo: "Fila evento" — registra el evento (solo si no es duplicado). Columnas = tabla valoria_eventos.
const ctx = $input.first().json;
if (ctx.duplicado) return [];
return [{ json: {
  evento_id: ctx.evento_id,
  caso_id: ctx.caso_id || '',
  canal: ctx.canal,
  tipo: ctx.tipo,
  ruta: ctx.ruta,
  usuario_ps: ctx.usuario_ps || '',
  recibido_en: ctx.recibido_en
} }];

// Nodo: "Acuse de recibo" — respuesta inmediata con folio (Telegram o voz).
const ctx = $('Decidir ruta').first().json;
const folio = ctx.caso_id || ctx.folio;
const texto = (ctx.ruta === 'aclarar' ? 'Aclaración recibida para ' : 'Caso creado: ') + folio +
  '\nEstado: en proceso (4 agentes + revisión). Te aviso al terminar. Resultado simulado.';
return [{ json: {
  canal: ctx.canal,
  chat_id: ctx.chat_id || '',
  texto: texto,
  voz: { ok: true, folio: folio, estado: 'en_proceso', mensaje: 'Caso ' + folio + ' creado. Se procesa en menos de un minuto y el asesor recibirá la propuesta en Telegram para aprobarla. Puedes pedirme el estado con el folio.' }
} }];

// Nodo: "Preparar aclaración" — solo el mismo usuario y solo si el caso pidió aclaración.
const ctx = $('Decidir ruta').first().json;
const filas = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.caso_id === ctx.folio; });
const caso = filas[0];
let ok = true, motivo = '';
if (!caso) { ok = false; motivo = 'No existe el caso ' + ctx.folio + '.'; }
else if (caso.estado !== 'requiere_aclaracion') { ok = false; motivo = 'El caso ' + ctx.folio + ' está en estado "' + caso.estado + '" y no admite aclaraciones.'; }
else if (caso.usuario_ps !== ctx.usuario_ps) { ok = false; motivo = 'Solo quien creó el caso puede aclararlo.'; }
if (!ok) {
  return [{ json: { valida: false, canal: ctx.canal, chat_id: ctx.chat_id, texto: motivo, voz: { ok: false, mensaje: motivo } } }];
}
const texto = (String(caso.texto_solicitud || '') + ' | Aclaración: ' + ctx.texto_mascarado).slice(0, 600);
return [{ json: {
  valida: true,
  fila: { caso_id: caso.caso_id, estado: 'recibido', texto_solicitud: texto, actualizado_en: new Date().toISOString() },
  caso_previo: { version_propuesta: Number(caso.version_propuesta || 0), iteraciones: Number(caso.iteraciones || 0), costo_usd: Number(caso.costo_usd || 0), limite_costo_usd: Number(caso.limite_costo_usd || 0), llamadas: Number(caso.llamadas || 0), demo: caso.demo || '' },
  texto_solicitud: texto
} }];

// Nodos auxiliares: devuelven un subcampo del ítem de entrada como ítem (o nada si está vacío).
// El generador reemplaza fila.
const v = $input.first().json['fila'];
return v ? [{ json: v }] : [];

// Nodo: "Formatear estado" — lee el registro persistente; nunca inventa un estado.
const ctx = $('Decidir ruta').first().json;
const filas = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.caso_id === ctx.folio; });
const caso = filas[0];
if (!caso) {
  const msg = 'No encontré el caso ' + ctx.folio + ' en el registro. Verifica el folio.';
  return [{ json: { canal: ctx.canal, chat_id: ctx.chat_id || '', texto: msg, voz: { ok: false, folio: ctx.folio, estado: 'no_encontrado', mensaje: msg }, expirar: null } }];
}
let estado = caso.estado;
let expirar = null;
if (estado === 'pendiente_aprobacion' && caso.aprobacion_expira_en && Date.now() > Date.parse(caso.aprobacion_expira_en)) {
  estado = 'expirado';
  expirar = { caso_id: caso.caso_id, estado: 'expirado', decision: 'expirado', decidido_por: 'sistema', decidido_en: new Date().toISOString(), actualizado_en: new Date().toISOString(), motivo: 'Venció el plazo de aprobación' };
}
let prop = null;
try { prop = caso.propuesta_json ? JSON.parse(caso.propuesta_json) : null; } catch (e) { prop = null; }
const m = prop && prop.metricas ? prop.metricas : null;
const etiquetas = {
  recibido: 'recibido', en_proceso: 'en proceso', pendiente_aprobacion: 'pendiente de aprobación del asesor',
  aprobado_simulado: 'aprobado (envío simulado)', rechazado: 'rechazado por el asesor', expirado: 'expirado sin aprobación',
  requiere_aclaracion: 'requiere aclaración', fuera_de_politica: 'fuera de política', bloqueado_politica: 'bloqueado por política',
  escalado_humano: 'escalado a revisión humana', detenido_presupuesto: 'detenido por presupuesto', detenido_limite: 'detenido por límite',
  error_validacion: 'error de validación', error_api: 'error del servicio de IA', error_skill: 'error al cargar skills'
};
const lineas = [
  'Caso ' + caso.caso_id + ' · ' + (etiquetas[estado] || estado),
  'Actualizado: ' + String(caso.actualizado_en || '').slice(0, 16).replace('T', ' ') + ' UTC',
  'Versión de propuesta: ' + (caso.version_propuesta || 0) + ' · iteraciones: ' + (caso.iteraciones || 0)
];
if (caso.perfil_riesgo) lineas.push('Perfil: ' + caso.perfil_riesgo + ' · monto: ' + caso.monto_mxn + ' MXN · horizonte: ' + caso.horizonte_anios + ' años');
if (m) lineas.push('Rendimiento esperado ilustrativo: ' + m.rend_esperado_anual_pct + '% anual · volatilidad aprox.: ' + m.volatilidad_aprox_pct + '%');
if (caso.motivo) lineas.push('Nota: ' + caso.motivo);
lineas.push('Resultado simulado; no constituye una recomendación.');
const texto = lineas.join('\n');
return [{ json: {
  canal: ctx.canal, chat_id: ctx.chat_id || '', texto: texto, expirar: expirar,
